definition.script:
// Configuration
var token = input.get("accessToken");
var userEmail = input.get("userEmail");
var selectFields = input.get("selectFields") || "";

// Validate inputs
if (!token) {
    log.error("Access token is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Access token is required");
    tags.trigger("error");
} else if (!userEmail) {
    log.error("User email is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "User email is required");
    tags.trigger("error");
} else {
    // Build URL
    var url = "https://graph.microsoft.com/v1.0/users/" + encodeURIComponent(userEmail);
    if (selectFields) {
        url += "?$select=" + selectFields;
    }

    // Headers for Graph API
    var headers = {
        "Authorization": "Bearer " + token,
        "Accept": "application/json"
    };

    log.info("Fetching user: " + userEmail);

    try {
        var response = http.get(url, headers);

        if (response.statusCode === 404) {
            log.warn("User not found: " + userEmail);
            output.set("User", null);
            output.set("UserJson", "");
            output.set("Found", false);
            output.set("HasErrors", false);
            output.set("ErrorMessage", "");
            tags.trigger("notfound");
        } else if (!response.isSuccess) {
            log.error("API error: HTTP " + response.statusCode);
            output.set("User", null);
            output.set("UserJson", "");
            output.set("Found", false);
            output.set("HasErrors", true);
            output.set("ErrorMessage", "API error: HTTP " + response.statusCode);
            tags.trigger("error");
        } else {
            var user = json.parse(response.body);
            log.info("Found user: " + (user.displayName || user.userPrincipalName));

            output.set("User", user);
            output.setJson("UserJson", user);
            output.set("Found", true);
            output.set("UserId", user.id || "");
            output.set("DisplayName", user.displayName || "");
            output.set("Mail", user.mail || "");
            output.set("UserPrincipalName", user.userPrincipalName || "");
            output.set("HasErrors", false);
            output.set("ErrorMessage", "");
            tags.trigger("success");
        }

    } catch (ex) {
        log.error("Exception: " + ex.message);
        output.set("User", null);
        output.set("UserJson", "");
        output.set("Found", false);
        output.set("HasErrors", true);
        output.set("ErrorMessage", "Exception: " + ex.message);
        tags.trigger("error");
    }
}
